def f(p, s):
    r = 1
    if p <= r or s <= r:
        return 1e10
    q = (p*s - r*p - r*s) / (p + s - r)
    if q <= 0:
        return 1e10
    return p/q + r/p + s/r + q/s

import numpy as np
from scipy.optimize import minimize

def objective(vars):
    p, s = vars
    return f(p, s)

best_f = 1e10
for _ in range(10):
    p0, s0 = np.random.rand(2) * 10
    p0 = max(p0, 2)
    s0 = max(s0, 2)
    res = minimize(objective, [p0, s0], bounds=[(1.1, 20), (1.1, 20)])
    if res.success:
        best_f = min(best_f, res.fun)

print(f"Best f: {best_f}")
